            if grid[r][c] != bg:
                points.setdefault(grid[r][c], []).append((r, c))

    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr == 0 or abs(dr) != abs(dc):
                    continue
                sr, sc = dr // abs(dr), dc // abs(dc)
                for r, c, vr, vc in ((r1, c1, -sr, -sc),
                                     (r2, c2, sr, sc)):
                    rr, cc = r + vr, c + vc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += vr
                        cc += vc
    return out
